def file_name_check(file_name):
    if not file_name or file_name.count('.') != 1:
        return 'No'

    name, extension = file_name.split('.', 1)

    if not name or not extension or not name[0].isalpha() or extension not in ['txt', 'exe', 'dll']:
        return 'No'

    digit_count = sum(c.isdigit() for c in file_name)

    if digit_count > 3:
        return 'No'

    return 'Yes'

